// The count table in `docs/architecture.md` is written from the archive rather
// than by hand, so a pull request that adds a record or a redrawing resolves a
// conflict on it by running one command instead of counting (#520).
//
// `npm run docs:counts` rewrites the tables between the two markers, one per
// series in `src/data/series/index.ts`, under its slug.
// `npm run gate:docs` (`--check`) writes nothing and fails when the committed
// table differs from what the script would write. The output goes through
// Prettier, so `format:check` passes on a freshly generated file.
import { readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { format, resolveConfig } from 'prettier'

import { importArchive, ROOT } from './archive-loader.mjs'
import { isMain } from './is-main.mjs'

/** The document the table sits in. */
// fallow-ignore-next-line security-sink -- a constant: the repository's own docs folder
export const DOC_PATH = path.join(ROOT, 'docs', 'architecture.md')

/** The row of arcs, places and ships names each kind so, in this order. */
const LANDS = { arc: 'arcs', place: 'places', ship: 'ships' }

const BEGIN =
  '<!-- Generated by `npm run docs:counts` from the archive. Do not edit by hand. -->'
const END = '<!-- End of the generated counts. -->'

/**
 * The document with the text between the markers replaced by the table.
 * @param {string} document The document as it sits on disk.
 * @param {string} table The table, without a trailing newline.
 * @returns {string} The document with the new table.
 */
export function withTable(document, table) {
  const start = document.indexOf(BEGIN)
  const end = document.indexOf(END)

  if (start === -1 || end < start) {
    throw new Error(
      'docs/architecture.md has lost the markers around the counts table.',
    )
  }

  return `${document.slice(0, start + BEGIN.length)}\n\n${table}\n\n${document.slice(end)}`
}

/**
 * Every entry of a field's timelines that hold some, one array per owner.
 * @param {{ field: string, timeline: { place?: string }[] }[]} timelines The archive's timelines.
 * @param {string} field The field.
 * @returns {{ place?: string }[][]} The timelines of that field.
 */
function filedIn(timelines, field) {
  return timelines
    .filter((owned) => owned.field === field)
    .map(({ timeline }) => timeline)
    .filter((timeline) => timeline.length > 0)
}

/**
 * The rows of dated steps, linked origins and later visits, each only where
 * the series files some. The table is what catches the archive losing
 * content (#1390): a drop of one shows as a changed line and fails
 * `gate:docs`.
 * @param {{ placeDossierOf: (place: unknown) => { visits?: unknown[] } | undefined, places: unknown[], timelines: { field: string, timeline: { place?: string }[] }[] }} archive The series' archive.
 * @returns {[string, number][]} The rows.
 */
function stepRows({ placeDossierOf, places, timelines }) {
  const steps = (field) => filedIn(timelines, field).flat()

  return [
    ['Dated timelines', timelines.length],
    ['Affiliation steps', steps('affiliation').length],
    ['Status steps', steps('status').length],
    [
      'Origins that link a place',
      steps('origin').filter((entry) => entry.place !== undefined).length,
    ],
    [
      'Later visits to places',
      places.flatMap((place) => placeDossierOf(place)?.visits ?? []).length,
    ],
  ].filter(([, count]) => count > 0)
}

/**
 * Whose the drawings are. Every drawing is a record's or a season heading's
 * (the data tests hold it), so the ones over the records are Game of
 * Thrones' seasons (#1601).
 * @param {Record<string, unknown>} drawings The series' first drawings.
 * @param {unknown[]} entities Its records.
 * @returns {string} The words after the count.
 */
function perRecord(drawings, entities) {
  const headings = Object.keys(drawings).length - entities.length

  return headings > 0 ?
      `one per record and ${headings} for the seasons' headings`
    : 'one per record'
}

/**
 * One series' table, counted from its archive, with a row for the devil
 * fruits, the ships and the bodies of power only where its description has
 * them.
 * @param {{ archive: { drawings: Record<string, unknown>, entities: { kind: string }[], features?: { power?: { bodies: { seats: unknown[] }[] } }, placeDossierOf: (place: unknown) => { visits?: unknown[] } | undefined, places: unknown[], sagas: unknown[], series: { features: { fruits: boolean, power?: boolean }, kinds: string[] }, timelines: { field: string, timeline: { place?: string }[] }[] } }} series The series, from the list.
 * @returns {string} The markdown table, not yet padded.
 */
export function countTable({ archive }) {
  const { drawings, entities, sagas, series, timelines } = archive
  const { fruits, power } = series.features
  const bodies = archive.features?.power?.bodies ?? []
  const lands = Object.keys(LANDS).filter((kind) => series.kinds.includes(kind))
  const ofKind = (kind) =>
    entities.filter((entity) => entity.kind === kind).length
  const redrawings = filedIn(timelines, 'redrawing')
  const chronicles = filedIn(timelines, 'chronicle')

  const rows = [
    ['Records', entities.length],
    ['Characters', ofKind('character')],
    ...(fruits ? [['Devil fruits', ofKind('fruit')]] : []),
    ...(series.kinds.includes('ability') ?
      [['Nen abilities', ofKind('ability')]]
    : []),
    ...(power ?
      [
        [
          'Bodies of power',
          `${bodies.length}, with ${bodies.flatMap(({ seats }) => seats).length} seats`,
        ],
      ]
    : []),
    [
      // Capitalised as a row label, whichever kind comes first.
      lands
        .map((kind) => LANDS[kind])
        .join(', ')
        .replace(/^./u, (first) => first.toUpperCase()),
      lands.map((kind) => ofKind(kind)).join(' · '),
    ],
    [
      'Saga modules',
      `${sagas.length}${fruits ? ', plus one for the devil fruits' : ''}`,
    ],
    [
      'Line drawings',
      `${Object.keys(drawings).length}, ${perRecord(drawings, entities)}, plus ${redrawings.flat().length} redrawings of ${redrawings.length} records`,
    ],
    [
      'Chronicle stories',
      `${chronicles.flat().length}, for ${chronicles.length} characters`,
    ],
    ...stepRows(archive),
  ]

  return [
    '| Thing | Count |',
    '| --- | --- |',
    ...rows.map(([thing, count]) => `| ${thing} | ${count} |`),
  ].join('\n')
}

/**
 * Every series' table under its slug, in the order of the list.
 * @returns {Promise<string>} The markdown, not yet padded.
 */
async function countTables() {
  const { SERIES, filedArchiveOf } = await importArchive('data/series/index.ts')

  const tables = await Promise.all(
    SERIES.map(async (series) => {
      const archive = await filedArchiveOf(series.slug)
      return `### \`${series.slug}\`\n\n${countTable({ archive })}`
    }),
  )
  return tables.join('\n\n')
}

/**
 * The document as it is, and as the script would write it.
 * @returns {Promise<{after: string, before: string}>} Both texts.
 */
async function render() {
  const before = readFileSync(DOC_PATH, 'utf8')
  const options = await resolveConfig(DOC_PATH)
  const after = await format(withTable(before, await countTables()), {
    ...options,
    filepath: DOC_PATH,
  })

  return { after, before }
}

if (isMain(import.meta)) {
  const { after, before } = await render()

  if (process.argv.includes('--check')) {
    if (after === before) {
      console.log('docs/architecture.md: the counts table is up to date.')
    } else {
      console.error(
        'docs/architecture.md: the counts table is stale: run npm run docs:counts',
      )
      process.exitCode = 1
    }
  } else {
    writeFileSync(DOC_PATH, after)
    console.log(
      after === before ?
        'docs/architecture.md is already up to date.'
      : 'docs/architecture.md: the counts table rewritten.',
    )
  }
}
